css:
.table {
    width: 100%;
    border-collapse: collapse;
}

.table,
.table th,
.table td {
    border: 1px solid black;
}

.table th,
.table td {
    padding: 8px;
    text-align: left;
}

.head_img {
    width: 50px;
    height: 50px;
    vertical-align: middle;
}

.header {
    margin-bottom: 20px;
}

hr {
    border: none;
    border-top: 2px solid black;
    margin: 20px 0;
}
.header h1 {
    display: inline-block;
    margin: 0 0 0 10px;
    font-size: 30px;
    vertical-align: middle;
}

.section{
    margin-top:5%;
}

.footer {
    margin-top: 50%;
}

.l{
    vertical-align:middle;
}
.v{
    display:inline-block;
    vertical-align:middle;
}
